// Button between P2 and GND, LED on P0
bool ledOn = false;
int lastBtn = HIGH;

void setup() {
  pinMode(P0, OUTPUT);
  pinMode(P2, INPUT_PULLUP);   // reads LOW while pressed
  Serial.begin(9600);
}

void loop() {
  int btn = digitalRead(P2);
  if (btn == LOW && lastBtn == HIGH) {
    ledOn = !ledOn;
    digitalWrite(P0, ledOn ? HIGH : LOW);
    Serial.println(ledOn ? "LED on" : "LED off");
    delay(50);   // debounce
  }
  lastBtn = btn;
}
